// AsyncEmitter wraps an existing audit emitter and emits events asynchronously
// using a configurable buffer size, applying a positive non-zero default when unset.
type AsyncEmitter struct {
	AsyncEmitterConfig
	eventsCh chan AuditEvent
	ctx      context.Context
	cancel   context.CancelFunc
	doneCh   chan struct{}
}

// NewAsyncEmitter creates an async audit emitter wrapping an existing emitter
// and starts its background forwarding loop.
func NewAsyncEmitter(cfg AsyncEmitterConfig) (*AsyncEmitter, error) {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	ctx, cancel := context.WithCancel(context.Background())
	emitter := &AsyncEmitter{
		AsyncEmitterConfig: cfg,
		eventsCh:           make(chan AuditEvent, cfg.BufferSize),
		ctx:                ctx,
		cancel:             cancel,
		doneCh:             make(chan struct{}),
	}
	go emitter.forwardEvents()
	return emitter, nil
}

// EmitAuditEvent enqueues an audit event for asynchronous forwarding without
// blocking the caller. Returns nil when an event is successfully enqueued.
func (e *AsyncEmitter) EmitAuditEvent(ctx context.Context, event AuditEvent) error {
	select {
	case e.eventsCh <- event:
		return nil
	case <-e.ctx.Done():
		return trace.ConnectionProblem(e.ctx.Err(), "async emitter is closed")
	case <-ctx.Done():
		return trace.ConnectionProblem(ctx.Err(), "context is closed")
	}
}

// Close cancels the async emitter background loop and closes the emitter.
func (e *AsyncEmitter) Close() error {
	e.cancel()
	<-e.doneCh
	return nil
}

// forwardEvents runs in a background goroutine and forwards events to the inner emitter
func (e *AsyncEmitter) forwardEvents() {
	defer close(e.doneCh)
	for {
		select {
		case event, ok := <-e.eventsCh:
			if !ok {
				return
			}
			// Forward the event to the inner emitter
			// Use a separate context to avoid blocking on slow emitter
			if err := e.Inner.EmitAuditEvent(e.ctx, event); err != nil {
				log.WithError(err).Debugf("Failed to forward audit event in async emitter.")
			}
		case <-e.ctx.Done():
			return
		}
	}
}

