+// CheckAndSetDefaults checks and sets default values for async emitter config
+func (cfg *AsyncEmitterConfig) CheckAndSetDefaults() error {
+	if cfg.Inner == nil {
+		return trace.BadParameter("missing parameter Inner")
+	}
+	if cfg.BufferSize <= 0 {
+		cfg.BufferSize = 1000
+	}
+	return nil
